def generate_left_region_output():
    output = [[0]*19 for _ in range(19)]

    h_start, h_end = 1, 9
    w_start, w_end = 1, 10

    for dr in range(h_start, h_end + 1):
        for dc in range(w_start, w_end + 1):
            h_center = (h_start + h_end) / 2
            w_center = (w_start + w_end) / 2
            dist_h = abs(dr - h_center)
            dist_w = abs(dc - w_center)
            dist = max(dist_h, dist_w)

            max_dist = max(abs(h_center - h_start), abs(w_center - w_start))

            layer_idx = 0
            if max_dist > 0:
                layer_idx = int(max_dist - dist)

            # Colors from outside in (reversed): 4, 1, 6, 3
            if layer_idx == 0:
                output[dr][dc] = 4
            elif layer_idx == 1:
                output[dr][dc] = 1
            elif layer_idx == 2:
                output[dr][dc] = 6
            else:
                output[dr][dc] = 3

    return output

